def solve(record):
    """
    Compute the length (in edges) of the shortest directed route.
    If source == target, the route must have positive length (a cycle).
    Return None when no such route exists.
    """
    # Extract the input tuple [edges, source, target]
    x = record['record_2']
    if not isinstance(x, list) or len(x) != 3:
        return None
    edges, src, dst = x

    # Build adjacency list for the directed graph
    adj = {}
    for u, v in edges:
        adj.setdefault(u, []).append(v)

    from collections import deque

    # Case: source and target are different – simple shortest path
    if src != dst:
        q = deque([(src, 0)])
        visited = {src}
        while q:
            node, dist = q.popleft()
            if node == dst:
                return dist
            for nb in adj.get(node, []):
                if nb not in visited:
                    visited.add(nb)
                    q.append((nb, dist + 1))
        return None

    # Case: source == target – need a positive‑length cycle
    # BFS that looks for the first return to src after at least one edge.
    q = deque([(src, 0)])
    visited = {src}
    while q:
        node, dist = q.popleft()
        for nb in adj.get(node, []):
            ndist = dist + 1
            if nb == src:          # found a cycle back to start
                return ndist
            if nb not in visited:
                visited.add(nb)
                q.append((nb, ndist))
    return None
